WITH joined AS (SELECT a.id, a.product_id, a.sale_date, a.units, d.launch_date FROM store_sales a LEFT JOIN products d ON a.product_id = d.id), joined_store_sales AS (SELECT a.*, d.brand FROM joined a LEFT JOIN products d ON a.product_id = d.id), metrics AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id, brand ORDER BY units DESC, id) row_seq, ROUND(units / SUM(units) OVER (PARTITION BY brand, product_id), 4) units_share FROM joined_store_sales), filtered AS (SELECT *, row_seq + units row_seq_plus_units FROM metrics WHERE brand IS NOT DISTINCT FROM 'Stark' AND row_seq IS NOT NULL) SELECT s.id, s.product_id, s.sale_date, s.units, s.launch_date, s.units_share, s.row_seq_plus_units, (SELECT AVG(t2.quantity) FROM order_items t2 WHERE t2.product_id = s.product_id) AS avg_order_item_quantity FROM filtered s
